# --- 자기 호출 ---

@Service
public class OrderService {
    public void cancelAll(List<Long> ids) {
        System.out.println(">>> cancelAll");
        for (Long id : ids) {
            cancel(id);                       // this.cancel
        }
    }

    @PreAuthorize("hasRole('ADMIN')")
    public void cancel(Long id) {
        System.out.println(">>> cancel " + id);
    }
}

$ curl -s -o /dev/null -w '%{http_code}\n' -b user.txt \
    -X POST localhost:8080/orders/cancel-all -d "ids=3,4&_csrf=$TOKEN"
302

>>> cancelAll
>>> cancel 3
>>> cancel 4

select id, status from orders where id in (3,4);

ID | STATUS
---+----------
3  | CANCELED
4  | CANCELED

#   검사가 안 돌았다

#   프록시를 안 거쳐서다

#   책 ⑥ 의 @Transactional 자기 호출과 같다

# --- 확인 ---

@GetMapping("/proxy-check")
@ResponseBody
public String proxyCheck() {
    return orderService.getClass().getName();
}

$ curl -s localhost:8080/proxy-check

com.example.OrderService$$SpringCGLIB$$0

#   빈은 프록시가 맞다

#   그런데 내부에서는 this 를 쓴다

#   해결: 호출하는 쪽을 밖으로 뺀다

@RestController
public class OrderController {
    public void cancelAll(List<Long> ids) {
        for (Long id : ids) {
            orderService.cancel(id);      // 프록시를 거친다
        }
    }
}

