# --- PostAuthorize 의 대가 ---

@PostAuthorize("returnObject.ownerEmail == authentication.name")
@Transactional
public Order cancelAndReturn(Long id) {
    Order order = repository.findById(id).orElseThrow();
    order.cancel();
    System.out.println(">>> canceled " + id);
    return order;
}

